  "inlineSchema": "// prisma/schema.prisma\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// Modèle User principal\nmodel User {\n  id       String   @id @default(uuid())\n  email    String   @unique\n  password String\n  role     UserRole @default(PATIENT)\n\n  // Informations personnelles\n  firstName      String\n  lastName       String\n  phone          String?\n  dateOfBirth    DateTime?\n  gender         Gender?\n  profilePicture String?\n\n  // Status et vérifications\n  isEmailVerified Boolean   @default(false)\n  isActive        Boolean   @default(true)\n  lastLoginAt     DateTime?\n\n  // Tokens de vérification\n  emailVerificationToken   String?\n  emailVerificationExpires DateTime?\n  passwordResetToken       String?\n  passwordResetExpires     DateTime?\n  refreshToken             String?\n  refreshTokenExpires      DateTime?\n\n  // Sécurité\n  loginAttempts    Int       @default(0)\n  lockUntil        DateTime?\n  twoFactorSecret  String?\n  twoFactorEnabled Boolean   @default(false)\n\n  // Relations\n  patient Patient?\n  doctor  Doctor?\n\n  // Timestamps\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@map(\"users\")\n}\n\n// Modèle Patient\nmodel Patient {\n  id     String @id @default(uuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Informations médicales spécifiques\n  bloodType        String?\n  allergies        String[]\n  chronicDiseases  String[]\n  emergencyContact Json? // {name, phone, relation}\n  insuranceInfo    Json? // {provider, policyNumber, etc}\n\n  // Relations\n  appointments   Appointment[]\n  medicalRecords String[] // IDs des dossiers médicaux en MongoDB\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"patients\")\n}\n\n// Modèle Doctor\nmodel Doctor {\n  id     String @id @default(uuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Informations professionnelles\n  licenseNumber   String    @unique\n  specialtyId     String\n  specialty       Specialty @relation(fields: [specialtyId], references: [id])\n  yearsExperience Int       @default(0)\n  education       String[]\n  certifications  String[]\n  languages       String[]\n\n  // Informations pratique\n  consultationFee Decimal? @db.Decimal(10, 2)\n  biography       String?\n  officeAddress   Json? // {street, city, postalCode, country}\n\n  // Status\n  isVerified  Boolean @default(false)\n  isAvailable Boolean @default(true)\n\n  // Relations\n  appointments Appointment[]\n  schedules    Schedule[]\n  reviews      Review[]\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"doctors\")\n}\n\n// Modèle Specialty (spécialités médicales)\nmodel Specialty {\n  id          String  @id @default(uuid())\n  name        String  @unique\n  description String?\n  icon        String?\n\n  // Relations\n  doctors Doctor[]\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"specialties\")\n}\n\n// Modèle Appointment\nmodel Appointment {\n  id String @id @default(uuid())\n\n  // Relations\n  patientId String\n  patient   Patient @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  doctorId  String\n  doctor    Doctor  @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n\n  // Informations du rendez-vous\n  scheduledAt DateTime\n  duration    Int               @default(30) // en minutes\n  status      AppointmentStatus @default(SCHEDULED)\n  type        AppointmentType   @default(CONSULTATION)\n\n  // Détails\n  reason   String\n  notes    String?\n  symptoms String[]\n\n  // Suivi\n  reminderSent Boolean   @default(false)\n  cancelReason String?\n  cancelledAt  DateTime?\n  cancelledBy  String? // patientId ou doctorId\n\n  // Relations avec MongoDB\n  medicalRecordId String? // ID du dossier médical créé après consultation\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"appointments\")\n}\n\n// Modèle Schedule (horaires des médecins)\nmodel Schedule {\n  id       String @id @default(uuid())\n  doctorId String\n  doctor   Doctor @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n\n  // Horaires\n  dayOfWeek Int // 0 = Dimanche, 1 = Lundi, etc.\n  startTime String // Format \"HH:MM\"\n  endTime   String // Format \"HH:MM\"\n\n  // Configuration\n  slotDuration Int     @default(30) // en minutes\n  breakStart   String? // Format \"HH:MM\"\n  breakEnd     String? // Format \"HH:MM\"\n\n  // Status\n  isActive Boolean @default(true)\n\n  // Exceptions (jours fériés, congés)\n  exceptions Json[] // [{date: \"YYYY-MM-DD\", reason: \"Holiday\"}]\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([doctorId, dayOfWeek])\n  @@map(\"schedules\")\n}\n\n// Modèle Review (avis des patients)\nmodel Review {\n  id String @id @default(uuid())\n\n  // Relations\n  patientId String\n  doctorId  String\n  doctor    Doctor @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n\n  // Contenu de l'avis\n  rating  Int     @db.SmallInt // 1-5 étoiles\n  comment String?\n\n  // Critères spécifiques\n  punctuality     Int? @db.SmallInt // 1-5\n  communication   Int? @db.SmallInt // 1-5\n  professionalism Int? @db.SmallInt // 1-5\n\n  // Status\n  isVerified Boolean @default(false)\n  isPublic   Boolean @default(true)\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([patientId, doctorId]) // Un seul avis par patient/médecin\n  @@map(\"reviews\")\n}\n\n// Modèle Notification\nmodel Notification {\n  id String @id @default(uuid())\n\n  // Destinataire\n  userId String\n\n  // Contenu\n  title   String\n  message String\n  type    NotificationType\n\n  // Données additionnelles\n  data Json?\n\n  // Status\n  isRead Boolean @default(false)\n\n  // Timestamps\n  createdAt DateTime  @default(now())\n  readAt    DateTime?\n\n  @@map(\"notifications\")\n}\n\n// Enums\nenum UserRole {\n  PATIENT\n  DOCTOR\n  ADMIN\n}\n\nenum Gender {\n  MALE\n  FEMALE\n}\n\nenum AppointmentStatus {\n  SCHEDULED // Planifié\n  CONFIRMED // Confirmé\n  IN_PROGRESS // En cours\n  COMPLETED // Terminé\n  CANCELLED // Annulé\n  NO_SHOW // Patient absent\n  RESCHEDULED // Reporté\n}\n\nenum AppointmentType {\n  CONSULTATION // Consultation générale\n  FOLLOW_UP // Suivi\n  EMERGENCY // Urgence\n  CHECK_UP // Bilan de santé\n  VACCINATION // Vaccination\n  SURGERY // Chirurgie\n  THERAPY // Thérapie\n}\n\nenum NotificationType {\n  APPOINTMENT_REMINDER\n  APPOINTMENT_CONFIRMED\n  APPOINTMENT_CANCELLED\n  APPOINTMENT_RESCHEDULED\n  MEDICAL_RECORD_UPDATED\n  SYSTEM_NOTIFICATION\n  PAYMENT_REMINDER\n}\n",
